 QPoint center(const QJsonObject& row){const auto l=row.value("label").toObject();return {qRound(l.value("x").toDouble()),qRound(l.value("y").toDouble())};}
 QRectF box(const QJsonObject& row,double padding=2){const auto l=row.value("label").toObject();const double t=l.value("angleDegrees").toDouble()*std::numbers::pi/180,c=std::abs(std::cos(t)),s=std::abs(std::sin(t)),w=l.value("width").toDouble(),h=l.value("height").toDouble();return QRectF(l.value("x").toDouble()-(w*c+h*s)/2,l.value("y").toDouble()-(w*s+h*c)/2,w*c+h*s,w*s+h*c).adjusted(-padding,-padding,padding,padding);}
 void readable(ReferenceView* v){const auto a=v->annotations();QVERIFY(a.size()==5);for(int i=0;i<a.size();++i){QVERIFY(!a[i].toObject().value("crowdedUnresolved").toBool());QVERIFY(v->rect().contains(center(a[i].toObject())));for(int j=i+1;j<a.size();++j)QVERIFY(!box(a[i].toObject()).intersects(box(a[j].toObject())));}}
 QWidget* receiver(QWidget* view,const QPoint& at){auto* hit=QApplication::widgetAt(view->mapToGlobal(at));if(!hit || (hit!=view && !view->isAncestorOf(hit)))qFatal("Pointer target is not actual viewport hit");return hit;}
 void click(ReferenceView* v,const QPoint& at,bool twice=false){auto* hit=receiver(v,at);const auto p=hit->mapFromGlobal(v->mapToGlobal(at));if(twice)QTest::mouseDClick(hit,Qt::LeftButton,Qt::NoModifier,p);else QTest::mouseClick(hit,Qt::LeftButton,Qt::NoModifier,p);}
 void drag(ReferenceView* v,const QPoint& start,const QPoint& finish){auto* hit=receiver(v,start);QTest::mousePress(hit,Qt::LeftButton,Qt::NoModifier,hit->mapFromGlobal(v->mapToGlobal(start)));auto* target=receiver(v,finish);const auto global=v->mapToGlobal(finish);QMouseEvent move(QEvent::MouseMove,QPointF(target->mapFromGlobal(global)),QPointF(global),Qt::NoButton,Qt::LeftButton,Qt::NoModifier);QApplication::sendEvent(target,&move);QTest::mouseRelease(target,Qt::LeftButton,Qt::NoModifier,target->mapFromGlobal(global));}
