  const auto firstId=dimensions.first().toObject().value("id").toString();const auto originalCenter=center(layout(view,firstId));drag(view,originalCenter,originalCenter+QPoint(12,0));QCOMPARE(draft(w),baseline);QCOMPARE(active(w).value("draftHistory"),history);QVERIFY(QLineF(center(layout(view,firstId)),originalCenter).length()<=1);
  call(w,"view.pan",{{"x",24},{"y",-16}});readable(view);QCOMPARE(draft(w),baseline);call(w,"window.resize",{{"width",1320},{"height",850}});QTest::qWait(60);readable(view);capture("dense-resized");QCOMPARE(draft(w),baseline);QCOMPARE(active(w).value("draftHistory"),history);
  call(w,"window.resize",{{"width",1500},{"height",950}});QTest::qWait(60);const auto anchor=call(w,"view.projectSketchPoint",{{"sketchId",sid},{"uMm",12},{"vMm",20}});call(w,"view.zoom",{{"factor",8},{"x",anchor.value("x")},{"y",anchor.value("y")}});call(w,"view.zoom",{{"factor",2},{"x",anchor.value("x")},{"y",anchor.value("y")}});readable(view);
  int unchanged=0;for(const auto& row:dimensions){const auto d=row.toObject();const auto display=layout(view,d.value("id").toString());if(!display.value("automaticPlacement").toBool()){const auto raw=view->dimensionLayout(baseline,d,d.value("valueMm").toDouble(),"mm");QCOMPARE(display,raw);++unchanged;}}QCOMPARE(unchanged,3);
  capture("source-local-mixed-layout");QCOMPARE(draft(w),baseline);QCOMPARE(active(w).value("draftHistory"),history);const auto sourceLocalLayouts=view->annotations();call(w,"sketch.finish");const auto final=call(w,"document.inspect");QCOMPARE(final.value("authored"),inspection.value("authored"));QCOMPARE(final.value("evaluation").toObject().value("bodies"),inspection.value("evaluation").toObject().value("bodies"));call(w,"document.save",{{"path",output+"/after.alloy"}});call(w,"document.open",{{"path",output+"/after.alloy"}});QCOMPARE(call(w,"document.inspect").value("authored"),inspection.value("authored"));call(w,"document.exportStl",{{"path",output+"/after.stl"},{"bodyIds",bodies},{"units","mm"},{"format","binary"},{"surfaceDeviationMm",.01},{"normalDeviationDeg",5}});
