  call(w,"document.new",{{"discard",true}});call(w,"sketch.begin",{{"plane","XY"}});const double xy[4][2]={{12,6},{32,10},{27,22},{9,18}};for(int n=0;n<4;++n)call(w,"sketch.line",{{"x1",xy[n][0]},{"y1",xy[n][1]},{"x2",xy[(n+1)%4][0]},{"y2",xy[(n+1)%4][1]},{"units","mm"}});const auto points=draft(w).value("parameters").toObject().value("points").toArray();for(int n=0;n<5;++n){const int a=n<4?n:0,b=n<4?(n+1)%4:2;call(w,"sketch.dimension",{{"kind","linear"},{"pointIds",QJsonArray{points[a].toObject().value("id"),points[b].toObject().value("id")}},{"value",std::hypot(xy[a][0]-xy[b][0],xy[a][1]-xy[b][1])},{"units","mm"},{"annotation",QJsonObject{{"uMm",n==0?22:n==1?40:n==2?18:n==3?0:22},{"vMm",n==0?0:n==1?16:n==2?30:n==3?12:16}}}});if(n==1){call(w,"sketch.lookAt");call(w,"view.fit");const auto local=call(w,"view.projectSketchPoint",{{"plane","XY"},{"uMm",22},{"vMm",14}});call(w,"view.zoom",{{"factor",8},{"x",local.value("x")},{"y",local.value("y")}});QCOMPARE(view->annotations().size(),2);capture("normal-two-dimensions");const auto current=draft(w);for(const auto& row:view->annotations()){const auto shown=row.toObject();QVERIFY(!shown.value("automaticPlacement").toBool());for(const auto& dim:current.value("parameters").toObject().value("dimensions").toArray())if(dim.toObject().value("id")==shown.value("dimensionId"))QCOMPARE(shown,view->dimensionLayout(current,dim.toObject(),dim.toObject().value("valueMm").toDouble(),"mm"));}capture("normal-two-dimensions");}}call(w,"sketch.lookAt");call(w,"view.zoom",{{"factor",.12}});readable(view);const auto ordinary=draft(w);QString dragged;for(const auto& row:view->annotations())if(row.toObject().value("automaticPlacement").toBool()){dragged=row.toObject().value("dimensionId").toString();break;}QVERIFY(!dragged.isEmpty());const auto press=center(layout(view,dragged));const auto target=press+QPoint(16,0);drag(view,press,target);QVERIFY(QLineF(center(layout(view,dragged)),target).length()<=1);const auto changed=draft(w);QVERIFY(changed!=ordinary);for(const auto* key:{"points","entities","constraints"})QCOMPARE(changed.value("parameters").toObject().value(key),ordinary.value("parameters").toObject().value(key));capture("ordinary-label-drag");call(w,"history.undo");QCOMPARE(draft(w),ordinary);call(w,"history.redo");QCOMPARE(draft(w),changed);
  QFile report(output+"/report.json");QVERIFY(report.open(QIODevice::WriteOnly));report.write(QJsonDocument(QJsonObject{{"passed",true},{"baseline",inspection},{"final",final},{"denseLayouts",denseLayouts},{"sourceLocalLayouts",sourceLocalLayouts},{"ordinaryBefore",ordinary},{"ordinaryAfter",changed},{"state",w.state()},{"transcript",transcript_}}).toJson());call(w,"sketch.cancel");call(w,"document.new",{{"discard",true}});w.close();
